'use strict';
const $ = (s,scope=document)=>scope.querySelector(s);
const $$ = (s,scope=document)=>Array.from(scope.querySelectorAll(s));
const esc = s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow = '<span class="arrow-circle" aria-hidden="true">›</span>';
const btn = (label,url)=>`<a class="button-link" href="${url}"><span>${label}</span>${arrow}</a>`;
const source = (url='company',extra='',checked='2026年9月6日')=>`<p class="source-note">出典：<a href="https://www.kanehide-tekko.co.jp/${url}" target="_blank" rel="noopener">金秀鉄工 公式サイト${url?'（'+({company:'会社情報',saiyo:'採用情報',seihin:'製品取扱',sekoujisseki:'施工実績',blog:'ブログ',business:'業務内容'}[url]||'掲載ページ')+'）':''}</a>　｜　${checked}確認${extra?'<br>'+extra:''}</p>`;
const table = rows=>`<table class="data-table"><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table>`;
const picture = (src,alt,cls='')=>`<img src="assets/${src}" alt="${esc(alt)}" class="${cls}" loading="lazy" width="1672" height="941">`;
const heading = (en,ja)=>`<div class="section-kicker">${ja}</div><h2 class="display-title">${en}</h2>`;
const brand = ()=>`<a href="index.html" class="brand" aria-label="金秀鉄工 トップページ"><img class="brand-logo" src="assets/kanehide-logo.png" width="655" height="129" alt="金秀鉄工株式会社 KANEHIDE IRONWORKS CO., LTD."></a>`;
let currentPage=STATIC_ARTICLE_ID?'news':(location.pathname.split('/').pop()||'index.html').replace('.html','');
if(!DATA.pages[currentPage])currentPage='index';
const companyLinks=['message','profile','organization','history','certifications','numbers','sdgs'];
const navLink=(page)=>`<a href="${page}.html">${DATA.pages[page][1]} <span class="red" aria-hidden="true">›</span></a>`;
const mailIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="4" width="20" height="16"/><path d="m2 5 10 8 10-8"/></svg>';
const phoneIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 2 3 4c-3 7 7 19 15 18l3-4-5-4-3 3c-3-1-5-3-6-6l3-3z"/></svg>';
$('#header').innerHTML=`${brand()}<nav class="desktop-nav" aria-label="メインメニュー"><button class="nav-item" data-menu="business" aria-expanded="false" aria-controls="mega">商品・施工実績<span class="plus">+</span></button><a class="nav-item" href="certifications.html">許可・認証</a><button class="nav-item" data-menu="company" aria-expanded="false" aria-controls="mega">会社概要<span class="plus">+</span></button><a class="nav-item" href="gallery.html">社員・工場</a><a class="nav-item" href="recruit.html">採用情報</a></nav><div class="header-cta"><a class="header-tile" href="contact.html" aria-label="お問い合わせ">${mailIcon}<span>お問い合わせ</span></a><a class="header-tile red-tile" href="tel:0989453351" aria-label="098-945-3351に電話">${phoneIcon}<span>お電話で<br>お問い合わせ</span></a><button class="menu-toggle" data-menu="all" aria-expanded="false" aria-controls="mega"><i class="hamburger" aria-hidden="true"></i><span>MENU</span></button></div>`;
$('#footer').innerHTML=`<a href="#" class="top-link" data-top>PAGETOP ${arrow}</a><div class="footer-main"><div class="footer-brand">${brand()}<p>〒903-0118<br>沖縄県中頭郡西原町字小波津567番地<br><a href="tel:0989453351">TEL 098-945-3351</a><br>FAX 098-945-9974</p></div><div class="footer-links"><div><strong>会社概要</strong>${companyLinks.slice(0,4).map(navLink).join('')}</div><div><strong>私たちの仕事</strong>${['business','products','works','certifications','numbers'].map(navLink).join('')}</div><div><strong>金秀鉄工を知る</strong>${['news','gallery','movies','recruit','sdgs','contact'].map(navLink).join('')}</div></div></div><div class="footer-bottom"><small>© 金秀鉄工株式会社</small></div>`;
const newsList = (limit=3)=>`<div class="news-list">${DATA.news.slice(0,limit).map((n,i)=>`<a class="news-row" href="news.html#${n.id?'post-'+n.id:'article-'+i}"><time>${n.date}</time><span class="tag">${n.cat}</span><span class="headline">${n.title}</span>${arrow}</a>`).join('')}</div>`;
const marquee=()=>`<div class="marquee" aria-hidden="true"><div>${Array.from({length:8},()=>'<span>A BATON FOR THE FUTURE.</span>').join('')}</div></div>`;
const MOVIES = {
 short:{title:'《 金秀鉄工㈱ 動画 》',label:'会社紹介動画（ショートバージョン）',poster:'uniform-meeting-oct10.png',src:'assets/company-short.mp4',note:'ショートバージョン'},
 interview:{title:'《 社員インタビュー 》',label:'社員インタビュー（ロングバージョン）',poster:'interview-long-poster.png',src:'assets/interview-long.mp4',note:'ロングバージョン'}
};
function movieThumbnail(id){
 const movie=MOVIES[id];
 if(id==='interview')return `<span class="interview-collage" aria-hidden="true">${[1,2,3].map(i=>`<img src="assets/interview-person-${i}-oct05.jpg" alt="" width="2048" height="1143" loading="lazy">`).join('')}</span>`;
 return `<img src="assets/${movie.poster}" alt="${movie.label}" width="2048" height="1138" loading="lazy">`;
}
function movieTeaser(id,modifier=''){
 const movie=MOVIES[id];
 return `<figure class="inline-movie ${modifier}"><button class="movie-thumb" data-movie="${id}" aria-label="${movie.label}を再生">${movieThumbnail(id)}<span class="play-disc" aria-hidden="true">▶</span></button><figcaption>${movie.title}</figcaption></figure>`;
}
const HOME_BUSINESS = DATA.business.map(b=>({...b,image:({steel:"top-steel-oct05.jpg",bridge:"top-bridge-oct05.jpg",frp:"frp-factory-cinematic-oct10.jpg",pile:"top-pile-oct05.jpg"})[b.id]||b.image,en:b.id==="frp"?"Fiber Reinforced Plastics":b.en}));
function businessJumpMenu(items=DATA.business){return `<nav class="business-jump-grid" aria-label="事業・製品紹介の一覧">${items.map(b=>`<a class="business-jump-card" href="${b.link}">${picture(b.image,b.title+'の事業イメージ')}<small>${b.en}</small><strong>${b.title}</strong></a>`).join('')}</nav>`;}
function playMovie(id){
 if(id==='factory'){openViewer(`<h2 id="viewer-title">鉄工場イメージ映像</h2><video controls autoplay playsinline poster="assets/factory.jpg" src="assets/factory.mp4"></video><p class="dialog-caption">AI生成映像・6秒／実際の工場映像ではありません。</p>`);return;}
 const movie=MOVIES[id];if(!movie)return;
 openViewer(`<h2 id="viewer-title">${movie.title}</h2><video controls autoplay playsinline preload="metadata" poster="assets/${movie.poster}" src="${movie.src}" aria-label="${movie.label}"></video><p class="dialog-caption">${movie.note}</p><p class="video-error" hidden>動画を読み込めませんでした。<a href="${movie.src}" target="_blank" rel="noopener">動画を直接開く</a></p>`);
 const video=$('#viewer-content video');
 video.addEventListener('error',()=>{$('.video-error').hidden=false;},{once:true});
}
function recruitBanner(){return `<section class="recruit-home" id="recruit"><div class="recruit-visual recruit-visual--collage" aria-label="工場で働く社員の写真"><div class="recruit-collage-frame"><img src="assets/uniform-factory-portrait-oct10.png" alt="新しいユニフォーム姿で工場に立つ金秀鉄工の社員4人" width="1536" height="864" loading="lazy"></div><div class="recruit-collage-frame"><img src="assets/recruit-real-sunset-oct05.jpg" alt="夕景の工場構内で話す金秀鉄工の社員4人" width="2048" height="1143" loading="lazy"></div></div><div class="recruit-content"><div class="section-kicker">採用情報</div><h2 class="display-title reveal">RECRUIT</h2><h3 class="reveal">鉄でつなげる 未来へのバトン</h3><figure class="inline-movie inline-movie--recruit"><button class="movie-thumb" data-movie="interview" aria-label="社員インタビュー（ロングバージョン）を再生">${movieThumbnail('interview')}<span class="play-disc" aria-hidden="true">▶</span></button><figcaption><span>INTERVIEW MOVIE</span>社員インタビュー</figcaption></figure>${btn('採用情報へ','recruit.html')}</div></section>`;}
const NUMBERS_AS_OF = '2026年10月1日時点';
function formatStatValue(value,group=true){return Number.isFinite(+value)?Number(value).toLocaleString('ja-JP',{useGrouping:group}):value;}
function stat(label,value,unit,note,count=true){const group=unit!=='年';const approximate=['工場敷地面積','工場建屋'].includes(label);return `<div class="stat reveal"><div class="label">${label}</div><div class="stat-value">${approximate?'<em class="stat-approx">約</em>':''}<span ${count?'data-count="'+value+'" data-grouping="'+group+'"':''}>${formatStatValue(value,group)}</span><em>${unit}</em></div><small>${note}</small></div>`;}

function home(){
 return `<div class="hero-world"><div class="world-sticky" aria-hidden="true"><img src="assets/hero-upload-poster.jpg" alt="" width="1280" height="720" fetchpriority="high"><video id="hero-video" autoplay loop muted playsinline preload="auto" poster="assets/hero-upload-poster.jpg"><source src="assets/hero-upload.mp4" type="video/mp4"></video></div><section class="hero"><div class="vertical-copy"><span>鉄でつなげる</span><span>未来へのバトン</span></div><h1 aria-label="A baton for the future"><span><b>A BATON</b></span><span><b>FOR THE FUTURE</b></span></h1><div class="hero-bottom"><a class="scroll-cue" href="#about"><i></i>SCROLL TO EXPLORE</a><span class="english-full">A baton for the future full of iron</span><button class="motion-button" id="motion-toggle" aria-label="背景映像を一時停止">Ⅱ <span>PAUSE</span></button></div></section><div class="news-strip"><strong>NEWS</strong><ul>${DATA.news.slice(0,3).map((n,i)=>`<li><a href="news.html#${n.id?'post-'+n.id:'article-'+i}"><time>${n.date}</time><span class="news-title">${n.title}</span><span class="red-dot">›</span></a></li>`).join('')}</ul></div><section class="about-home" id="about"><div class="about-heading reveal">${heading('ABOUT','会社概要')}</div><div class="about-layout"><div class="about-copy"><h3 class="reveal">安全は<br>全てに優先する。</h3><p class="reveal">全員で安全活動に取り組もう、安全を最優先に、<br>社員の皆さんと一緒に安心して働ける会社を<br>築いて行きます。</p>${btn('会社概要','company.html')}</div><figure class="inline-movie about-movie reveal"><button class="movie-thumb" data-movie="short" aria-label="会社紹介動画（ショートバージョン）を再生"><img src="assets/${MOVIES.short.poster}" alt="会社紹介動画（ショートバージョン）" width="2048" height="1138" loading="lazy"><span class="play-disc" aria-hidden="true">▶</span></button><figcaption><span>COMPANY MOVIE</span>金秀鉄工 会社紹介動画</figcaption></figure></div><nav class="about-links" aria-label="会社情報の詳細">${companyLinks.slice(0,4).map((page,i)=>`<a href="${page}.html"><span class="about-link-number">0${i+1}</span><span class="about-link-label">${DATA.pages[page][1]}</span></a>`).join('')}</nav></section></div><section class="section business-home"><div class="section-topline"><div class="reveal">${heading('BUSINESS','商品情報・施工実績')}</div><div class="business-overview-links"><a class="text-link" href="business.html">業務内容へ ${arrow}</a><a class="text-link" href="works.html">施工実績一覧へ ${arrow}</a></div></div>${businessJumpMenu(HOME_BUSINESS)}<div class="business-panels">${HOME_BUSINESS.map(b=>`<article class="business-panel" id="business-${b.id}" tabindex="-1" aria-label="${b.title}"><div class="business-info"><span class="business-num">${b.n}</span><h3>${b.title}</h3><span class="english-label">${b.en}</span><p>${b.text}</p>${btn(b.title+'の紹介へ',b.link)}</div><div class="business-image">${picture(b.image,b.title+'のAI生成イメージ')}${b.id==='frp'?'<span class="asset-label">AI IMAGE / 事業イメージ</span>':''}</div></article>`).join('')}</div></section><section class="wide-feature"><a class="feature-photo" href="certifications.html">${picture('top-bridge-oct05.jpg','ご提供の橋梁写真を参考に再生成したイメージ')}<div class="feature-content"><span class="eyebrow">QUALITY & SAFETY</span><h2>良い仕事をして<br>お客様の信頼を得る</h2><span>許可・認証</span>${arrow}</div></a><a class="feature-photo" href="gallery.html">${picture('top-staff-oct05.jpg','ご提供の社員写真を参考に再生成したイメージ')}<div class="feature-content"><span class="eyebrow">PEOPLE & FACTORY</span><h2>社員・構内／<br>事務所写真</h2><span>金秀鉄工を知る</span>${arrow}</div></a></section><section class="numbers-preview"><div class="section-topline"><div>${heading('IN NUMBERS','数字で見る金秀鉄工')}</div><a class="text-link" href="numbers.html">もっと見る <span class="arrow-circle" style="color:white;border-color:white">›</span></a></div><p class="numbers-as-of">${NUMBERS_AS_OF}</p><div class="stats-grid">${stat('創業',1947,'年',DATA.companyDates.founded)}${stat('社員数',72,'名','役員、契約社員含')}${stat('工場敷地面積',49000,'m²','公式サイト掲載値')}</div></section><section class="section"><div class="section-topline"><div class="reveal">${heading('NEWS','お知らせ')}</div><a class="text-link" href="news.html">お知らせ一覧へ ${arrow}</a></div>${newsList()}</section>${recruitBanner()}${marquee()}`;
}
function pageHead(){const [en,ja]=DATA.pages[currentPage];return `<section class="page-heading"><img class="head-decoration" src="assets/hero.jpg" alt=""><div class="breadcrumb"><a href="index.html">TOP</a><span>/</span><span>${ja}</span></div><div class="section-kicker">${ja}</div><h1>${en}</h1></section>`;}
function company(){
 const items=[['message','代表挨拶'],['profile','会社情報・建設業許可'],['organization','組織図'],['history','沿革'],['certifications','許可・認証'],['numbers','数字で見る金秀鉄工'],['sdgs','SDGsへの取り組み']];
 return `<h2 class="page-intro reveal">私たち、<br>金秀鉄工株式会社とは？</h2><nav class="pill-nav company-overview-nav" aria-label="会社概要の項目">${items.map(([id,t])=>`<a href="#company-${id}">${t}</a>`).join('')}</nav><section class="company-summary section-anchor" id="company-message"><div class="company-summary-heading"><span class="english-label">01 / MESSAGE</span><h2>代表挨拶</h2></div><div class="company-message-summary"><figure>${picture('president-teruya.jpg','代表取締役社長 照屋 賢治')}<figcaption>代表取締役社長　照屋 賢治</figcaption></figure><div><h3>安全は全てに優先する。</h3><p>${esc(DATA.messageFull[0])}</p><p>${esc(DATA.messageFull[1]||'')}</p>${btn('続きを読む','message.html')}</div></div></section><section class="company-summary section-anchor" id="company-profile"><div class="company-summary-heading"><span class="english-label">02 / PROFILE</span><h2>会社情報・建設業許可</h2></div>${table(companyProfileRows())}${profileRevisionNote()}<h3>建設業許可</h3>${table(DATA.certifications.slice(0,2))}${btn('役員・取引先などを続きを読む','profile.html')}</section><section class="company-summary section-anchor" id="company-organization"><div class="company-summary-heading"><span class="english-label">03 / ORGANIZATION</span><h2>組織図</h2></div><div class="organization-image"><img src="assets/organization.png" alt="金秀鉄工の組織図" width="1132" height="311" loading="lazy"></div><p>管理本部・営業本部・工務本部・生産本部の4本部で構成しています。</p>${btn('組織の詳細を読む','organization.html')}</section><section class="company-summary section-anchor" id="company-history"><div class="company-summary-heading"><span class="english-label">04 / HISTORY</span><h2>沿革</h2></div><div class="timeline">${[...DATA.history.slice(0,2),...DATA.history.slice(-3)].map(([y,m,t])=>`<div class="timeline-row"><div class="timeline-year">${y}<small>${m}</small></div><p>${t}</p></div>`).join('')}</div>${btn('沿革をすべて読む','history.html')}</section><section class="company-summary section-anchor" id="company-certifications"><div class="company-summary-heading"><span class="english-label">05 / QUALITY & SAFETY</span><h2>許可・認証</h2></div><div class="cert-tiles"><div class="cert-tile"><strong>H GRADE</strong><p>鋼構造物製作工場<br>Hグレード認定</p></div><div class="cert-tile"><strong>ISO 9001</strong><p>品質</p></div><div class="cert-tile"><strong>ISO 45001</strong><p>労働安全衛生</p></div></div>${btn('許可・認証・資格を続きを読む','certifications.html')}</section><section class="company-summary section-anchor" id="company-numbers"><div class="company-summary-heading"><span class="english-label">06 / IN NUMBERS</span><h2>数字で見る金秀鉄工</h2></div><p class="numbers-as-of">${NUMBERS_AS_OF}</p><div class="company-stats">${stat('創業',1947,'年',DATA.companyDates.founded)}${stat('社員数',72,'名','役員、契約社員含／公式掲載値')}${stat('工場敷地面積',49000,'m²','公式掲載値')}</div>${btn('ほかの数字を見る','numbers.html')}</section><section class="company-summary section-anchor" id="company-sdgs"><div class="company-summary-heading"><span class="english-label">07 / SDGs</span><h2>SDGsへの取り組み</h2></div><div class="company-sdg-grid">${DATA.sdgGroups.map(g=>`<section><span class="sdg-number">${g.goal}</span><h3>${g.title}</h3><ul>${g.items.slice(0,3).map(t=>`<li>${t}</li>`).join('')}</ul></section>`).join('')}</div>${btn('活動を続きを読む','sdgs.html')}</section>${source('company','SDGsの活動内容は公式採用情報をもとに整理しています。','2026年10月3日')}`;
}

