function sdgs(){return `<h2 class="page-intro reveal">金秀鉄工の<br>SDGsへの取り組み</h2><nav class="pill-nav" aria-label="SDGsの取り組み一覧">${DATA.sdgGroups.map(g=>`<a href="#goal-${g.goal}">${g.title}</a>`).join('')}</nav>${DATA.sdgGroups.map(g=>`<section class="product-section" id="goal-${g.goal}"><div><span class="sdg-number">${g.goal}</span><h2>${g.title}</h2></div><div><ul>${g.items.map(t=>`<li>${t}</li>`).join('')}</ul>${g.image?officialFigure(g.image,g.caption):''}</div></section>`).join('')}<section class="content-section"><h2 class="subheading">社内での学びと交流</h2><div class="official-grid">${officialFigure('official/recruit-04.jpg','社内溶接コンクールの開催')}${officialFigure('official/recruit-06.jpg','女性職員による評価')}</div></section><div class="business-related">${btn('採用情報へ','recruit.html')}${btn('関連するお知らせ','news.html')}</div>${source('saiyo','公式サイトに掲載された活動を分野別に整理しています。','2026年10月3日')}`;}
function contact(){return `<h2 class="page-intro reveal">お問い合わせ</h2><p class="reading-copy">製品・施工、採用、資料のご請求など、ご用件に合わせてご相談ください。</p><div class="contact-options"><section class="soft-panel"><span class="english-label">PHONE</span><h2>お電話でのお問い合わせ</h2><a class="contact-phone" href="tel:0989453351">098-945-3351</a><p>FAX 098-945-9974</p><p class="contact-help">受付時間は営業日にご確認ください。</p></section><section class="soft-panel contact-guidance"><span class="english-label">CONTACT FORM</span><h2>フォームでのお問い合わせ</h2><p>下記フォームへ必要事項をご入力ください。送信時に迷惑メール対策の確認画面へ移動します。担当者が内容を確認し、折り返しご連絡いたします。</p><p><strong>「<span class="required-mark">必須</span>」は必須項目です。</strong></p></section></div><section class="content-section contact-form-section" aria-labelledby="contact-form-title"><div class="contact-form-heading"><span class="english-label">INQUIRY</span><h2 class="subheading" id="contact-form-title">お問い合わせフォーム</h2></div><form id="contact-form" class="contact-form" method="POST" action="https://formsubmit.co/1116maehira@gmail.com"><input type="hidden" name="_cc" value="shuya.sakihama@kanehide.co.jp,haruka.kiyuna@kanehide.co.jp,ya-miyagi@kanehide.co.jp,i-isiki@kanehide.co.jp"><input type="hidden" name="_template" value="table"><input type="hidden" name="_subject" value="【金秀鉄工Web】お問い合わせ"><div class="form-grid"><label><span>お名前 <em>必須</em></span><input name="name" autocomplete="name" maxlength="100" required></label><label><span>会社名</span><input name="company" autocomplete="organization" maxlength="160"></label><label><span>メールアドレス <em>必須</em></span><input name="email" type="email" autocomplete="email" maxlength="200" required></label><label><span>電話番号</span><input name="phone" type="tel" autocomplete="tel" maxlength="50" inputmode="tel"></label><label class="form-wide"><span>お問い合わせ種別</span><select name="category"><option value="">選択してください</option><option>製品・施工について</option><option>採用について</option><option>資料のご請求</option><option>その他</option></select></label><label class="form-wide"><span>件名 <em>必須</em></span><input name="subject" maxlength="200" required></label><fieldset class="form-wide"><legend>希望する返答方法</legend><div class="radio-row"><label><input type="radio" name="reply_method" value="メール" checked> メール</label><label><input type="radio" name="reply_method" value="電話"> 電話</label><label><input type="radio" name="reply_method" value="指定なし"> 指定なし</label></div></fieldset><label class="form-wide"><span>お問い合わせ内容 <em>必須</em></span><textarea name="message" rows="9" maxlength="5000" required></textarea></label><label class="honeypot" aria-hidden="true">ウェブサイト<input name="_honey" tabindex="-1" autocomplete="off"></label></div><label class="privacy-check"><input name="privacy" type="checkbox" required><span>入力内容をお問い合わせへの回答に利用すること、および外部フォームサービス（FormSubmit）を通じて送信することに同意します。</span></label><p id="contact-status" class="contact-status" role="status" aria-live="polite"></p><button class="contact-submit" type="submit"><span>入力内容を送信する</span><span class="arrow-circle">›</span></button></form></section><section class="content-section"><h2 class="subheading">ご相談内容</h2><div class="contact-topics">${[['製品・施工について','建築鉄骨、橋梁鉄骨、FRP製品、鋼管杭のご相談','商品情報を見る','products.html'],['採用について','募集要項・職場環境・応募に関するご相談','採用情報を見る','recruit.html'],['資料のご請求','製品資料・パンフレットに関するご相談','製品資料の案内','products.html#documents'],['その他','上記以外のお問い合わせ','会社情報を見る','profile.html']].map(([t,p,l,u])=>`<section><h3>${t}</h3><p>${p}</p>${btn(l,u)}</section>`).join('')}</div></section><section class="content-section"><h2 class="subheading">所在地</h2><p class="reading-copy">金秀鉄工株式会社<br>〒903-0118<br>沖縄県中頭郡西原町字小波津567番地</p></section>${source('contact','','2026年10月3日')}`;}

function setupContactForm(){
 const form=$('#contact-form');if(!form)return;
 const status=$('#contact-status');const button=form.querySelector('button[type="submit"]');
 const cfg=window.KANEHIDE_CONFIG||{};
 form.action=cfg.contactEndpoint||'https://formsubmit.co/1116maehira@gmail.com';form.method='POST';
 const hidden=(name,value)=>{let input=form.elements.namedItem(name);if(!input){input=document.createElement('input');input.type='hidden';input.name=name;form.append(input);}input.value=value;};
 hidden('_cc',(cfg.recipients||["1116maehira@gmail.com","shuya.sakihama@kanehide.co.jp","haruka.kiyuna@kanehide.co.jp","ya-miyagi@kanehide.co.jp","i-isiki@kanehide.co.jp"]).slice(1).join(','));
 hidden('_template','table');
 hidden('_next',new URL('contact-thanks.html',location.href).href);
 window.addEventListener('pageshow',()=>{button.disabled=false;button.querySelector('span').textContent='入力内容を送信する';});
 form.addEventListener('submit',e=>{
  e.preventDefault();status.textContent='';status.className='contact-status';
  for(const key of ['name','email','subject','message']){const input=form.elements.namedItem(key);input.value=input.value.trim();}
  const phone=form.elements.namedItem('phone');phone.setCustomValidity('');
  if(form.elements.namedItem('reply_method').value==='電話'&&!phone.value.trim())phone.setCustomValidity('電話での回答をご希望の場合は電話番号をご入力ください。');
  if(!form.reportValidity())return;
  if(form.elements.namedItem('_honey').value)return;
  if(button.disabled)return;
  hidden('_subject','【金秀鉄工Web】'+form.elements.namedItem('subject').value);
  button.disabled=true;button.querySelector('span').textContent='送信画面へ移動中…';
  status.textContent='送信サービスへ接続しています。次の画面で確認を完了してください。';
  try{HTMLFormElement.prototype.submit.call(form);}catch{button.disabled=false;button.querySelector('span').textContent='入力内容を送信する';status.className='contact-status error';status.textContent='送信画面へ移動できませんでした。入力内容は残っています。再度お試しいただくか、お電話でお問い合わせください。';}
 });
}
let newsCategory='すべて';
function news(){return `<div id="news-content"></div>`;}
function renderNews(){const m=location.hash.match(/^#article-(\d+)$/);const n=m?DATA.news[Number(m[1])]:null;if(n){$('#news-content').innerHTML=`<article class="news-article"><a class="back-link" href="news.html">‹ お知らせ一覧へ</a><div><time>${n.date}</time> <span class="tag">${n.cat}</span></div><h2>${esc(n.title)}</h2>${n.date<'2025.01.01'?'<p class="archive-label">過去のお知らせです。募集・イベント・営業日の案内は掲載当時の情報です。</p>':''}<h3 class="news-summary-label">記事概要</h3><p class="reading-copy">${esc(n.body)}</p>${n.image?officialFigure(n.image,n.title,'document'):''}${btn('公式記事を読む',n.url)}${source('blog','概要は公式掲載情報に基づき整理しています。画像を押すと拡大できます。','2026年10月3日')}</article>`;return;}$('#news-content').innerHTML=`<nav class="pill-nav" aria-label="お知らせのカテゴリ">${['すべて','お知らせ','イベント','表彰','その他'].map(cat=>`<button data-news-category="${cat}" class="${cat===newsCategory?'active':''}" aria-pressed="${cat===newsCategory}">${cat}</button>`).join('')}</nav><p class="news-count" role="status">${DATA.news.filter(n=>newsCategory==='すべて'||n.cat===newsCategory).length}件</p><div class="news-list">${DATA.news.map((n,i)=>({n,i})).filter(({n})=>newsCategory==='すべて'||n.cat===newsCategory).map(({n,i})=>`<a class="news-row" href="news.html#${n.id?'post-'+n.id:'article-'+i}"><time>${n.date}</time><span class="tag">${n.cat}</span><span class="headline">${esc(n.title)}</span>${arrow}</a>`).join('')||'<p class="empty-news">このカテゴリの掲載記事はありません。</p>'}</div>${source('blog','公式ブログで確認した20件を掲載。カテゴリは記事の内容に基づき整理しています。','2026年10月3日')}${btn('公式ブログを見る','https://www.kanehide-tekko.co.jp/blog')}`;}

const DIVISION_INTRO={
 steel:{lead:'建物の骨格をつくる、柱と梁。',image:'steel-structure-intro.jpg',paragraphs:['建築鉄骨は、鋼材でつくった柱や梁を組み合わせ、建物を支える骨組みです。商業施設、工場、倉庫など、さまざまな建築物で使われています。','設計図に基づいて部材を加工し、現場で組み立てて一つの構造にしていきます。完成後は外壁や内装の内側に隠れる部分ですが、建物を支える重要な役割を担います。'],points:[['柱・梁','柱と梁を接合し、建物の骨組みを構成します。'],['工場での製作','図面に合わせて鋼材を切断・加工し、部材を組み立てます。'],['現場での組立','製作した部材を現場へ運び、計画に沿って建て方を進めます。']]},
 bridge:{lead:'人とまちをつなぐ、橋の骨組み。',image:'bridge-structure-intro.jpg',paragraphs:['橋梁鉄骨は、橋を支える桁などに用いられる鋼製の構造部材です。川や道路を越えて、人や車が行き来するための橋を形づくります。','橋の長さや設置場所、使い方に応じて構造や部材を検討します。工場での製作から運搬、現場での架設まで、各工程をつないで構築していきます。'],points:[['橋を支える鋼材','桁などの鋼製部材を組み合わせ、橋の構造を形づくります。'],['現場に合わせた計画','河川や道路など、設置場所の条件を踏まえて工事を計画します。'],['製作から架設へ','工場で製作した部材を運び、現場で設置・接合します。']]}
};
function divisionIntroduction(id){
 const b=DATA.business.find(x=>x.id===id),d=DIVISION_INTRO[id];
 if(!d)return productDescription(id).replace(/<a class="button-link" href="works.html#[^"]+">[\s\S]*?<\/a>/,'');
 return `<div class="division-intro-grid"><div><span class="english-label">${b.en}</span><h2>${d.lead}</h2>${d.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div><figure class="division-visual">${picture(d.image,b.title+'を表すAI生成イメージ')}<figcaption>AI生成イメージ／実際の施工物件ではありません</figcaption></figure></div><div class="division-points">${d.points.map(([title,body],i)=>`<section><span class="english-label">0${i+1}</span><h3>${title}</h3><p>${body}</p></section>`).join('')}</div><p class="source-note">上記は${b.title}についての一般的な紹介です。個別の仕様・対応範囲はお問い合わせください。</p><section class="content-section"><h2 class="subheading">金秀鉄工の業務体制</h2><p class="reading-copy">営業・積算、図面の作成、製作、品質管理、現場での設置・組立に関する業務を、各部署が担っています。</p><div class="business-related">${btn('業務内容を詳しく見る','business.html')}${btn('許可・認証を見る','certifications.html')}</div></section>`;
}
function division(id){const b=DATA.business.find(x=>x.id===id);return `<nav class="pill-nav division-local-nav" aria-label="${b.title}のページ内メニュー"><a href="#introduction">${b.title}の紹介</a>${id!=='pile'?'<a href="#projects">施工実績</a>':''}<a href="#inquiry">お問い合わせ</a></nav><section class="section-anchor division-introduction" id="introduction" aria-label="${b.title}の紹介">${divisionIntroduction(id)}</section>${id==='bridge'?`<section class="content-section"><h2 class="subheading">取り扱い製品</h2>${productDescription('panel')}${productDescription('kakuta')}</section>`:''}${id==='frp'?`<section class="content-section"><h2 class="subheading">製品資料・許可証</h2>${btn('資料を見る','products.html#documents')}</section>`:''}${id!=='pile'?`<section class="content-section section-anchor division-projects" id="projects"><span class="english-label">PROJECTS</span><h2 class="division-section-title">施工実績</h2>${workContent(id)}${source('sekoujisseki','写真・工事名は公式サイトの施工実績に基づいて掲載しています。','2026年10月3日')}</section>`:''}<section class="section-anchor division-inquiry" id="inquiry"><div><span class="english-label">CONTACT</span><h2>${b.title}についての<br>お問い合わせ</h2><p>${id==='pile'?'鋼管杭製品の販売・資料に関するご相談はこちらから。':'製品・施工に関するご相談はこちらから。'}</p></div><div class="division-inquiry-actions">${btn('お問い合わせへ','contact.html')}<a class="division-phone" href="tel:0989453351">098-945-3351<span>お電話でのお問い合わせ</span></a></div></section>${source(id==='steel'?'business':'seihin',id==='steel'||id==='bridge'?'一般的な紹介説明とAI生成イメージを追加しています。会社固有の情報は公式サイトに基づいています。':'製品紹介は公式サイト掲載内容をもとに整理しています。','2026年10月3日')}<nav class="pill-nav division-other-nav" aria-label="ほかの分野を見る">${DATA.business.filter(x=>x.id!==id).map(x=>`<a href="${x.link}">${x.title}</a>`).join('')}</nav>`;}

const renderers={steel:()=>division('steel'),bridge:()=>division('bridge'),frp:()=>division('frp'),pile:()=>division('pile'),company,message,profile,organization,history:historyPage,business,products,works,certifications,numbers,gallery,movies,recruit,news,sdgs,contact};
function renderPage(){document.body.classList.toggle('inner',currentPage!=='index');document.body.classList.toggle('division-page',['steel','bridge','frp','pile'].includes(currentPage));$('#main').innerHTML=currentPage==='index'?home():pageHead()+`<div class="page-body">${renderers[currentPage]()}</div>`;document.title=STATIC_SITE_META[STATIC_ARTICLE_ID?'news-'+STATIC_ARTICLE_ID:currentPage]?.title||document.title;if(currentPage==='works')renderWorks(location.hash.slice(1));if(currentPage==='news')renderNews();setupMotion();if(currentPage==='gallery')setupGallery();if(currentPage==='contact')setupContactForm();}
let menuOpen='';let closeTimer;
function closeMenu(){menuOpen='';$('#mega').hidden=true;$$('[data-menu]').forEach(e=>e.setAttribute('aria-expanded','false'));$('.menu-toggle span').textContent='MENU';}
function openMenu(key){clearTimeout(closeTimer);menuOpen=key;let content='';if(key==='business'){content=`<div class="mega-grid">${HOME_BUSINESS.map(b=>`<a class="mega-card" href="${b.link}"><figure>${picture(b.image,b.title+'のAI生成イメージ')}</figure><small>${b.en}</small><strong>${b.title}</strong></a>`).join('')}</div><div class="mega-bottom"><a href="business.html">業務内容</a><a href="products.html">商品情報一覧 ›</a><a href="works.html">施工実績一覧 ›</a></div>`;}else{const list=key==='all'?Object.keys(DATA.pages).filter(x=>x!=='index'):companyLinks;content=`<div class="mega-title">${key==='all'?'MENU':'COMPANY'}</div><div class="mega-links">${list.map(navLink).join('')}</div>`;}$('#mega').innerHTML=content+`<div class="mega-bottom"><span>鉄でつなげる 未来へのバトン</span><button class="mega-dismiss" data-close-menu aria-label="メニューを閉じる">×</button></div>`;$('#mega').hidden=false;$$('[data-menu]').forEach(e=>e.setAttribute('aria-expanded',e.dataset.menu===key?'true':'false'));$('.menu-toggle span').textContent='CLOSE';}
$$('[data-menu]').forEach(el=>{el.addEventListener('click',()=>menuOpen===el.dataset.menu?closeMenu():openMenu(el.dataset.menu));el.addEventListener('mouseenter',()=>{if(matchMedia('(hover:hover)').matches&&el.dataset.menu!=='all')openMenu(el.dataset.menu);});el.addEventListener('mouseleave',()=>{closeTimer=setTimeout(closeMenu,180);});el.addEventListener('focus',()=>{clearTimeout(closeTimer);});});$('#mega').addEventListener('mouseenter',()=>clearTimeout(closeTimer));$('#mega').addEventListener('mouseleave',()=>{if(matchMedia('(hover:hover)').matches)closeTimer=setTimeout(closeMenu,180);});$('#mega').addEventListener('focusin',()=>clearTimeout(closeTimer));
let lastFocus=null;
function openViewer(content){lastFocus=document.activeElement;$('#viewer-content').innerHTML=content;$('#viewer').showModal();document.body.style.overflow='hidden';$('.dialog-close').focus();}
function closeViewer(){$('#viewer').close();}
$('#viewer').addEventListener('close',()=>{$('#viewer-content').innerHTML='';document.body.style.overflow='';lastFocus?.focus();});$('.dialog-close').addEventListener('click',closeViewer);$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer')){const r=$('#viewer').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeViewer();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();}if(e.key==='Tab'&&menuOpen){setTimeout(()=>{if(!$('#mega').contains(document.activeElement)&&!document.activeElement.closest('[data-menu]'))closeMenu();},0);}});
document.addEventListener('click',e=>{const el=e.target.closest('a,button');if(!el){if(menuOpen&&!e.target.closest('#mega'))closeMenu();return;}if(el.hasAttribute('data-close-menu'))return closeMenu();if(el.hasAttribute('data-top')){e.preventDefault();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}if(el.dataset.galleryGo!==undefined){goGallery(+el.dataset.galleryGo);return;}if(el.dataset.galleryStep){goGallery(galleryIndex+Number(el.dataset.galleryStep));return;}if(el.dataset.newsCategory){newsCategory=el.dataset.newsCategory;renderNews();return;}if(el.dataset.officialImage){openViewer(`<h2 id="viewer-title">${esc(el.dataset.title)}</h2><img src="assets/${el.dataset.officialImage}" alt="${esc(el.dataset.title)}"><p class="dialog-caption">金秀鉄工公式サイト掲載資料</p>`);return;}if(el.dataset.gallery){openViewer(`<h2 id="viewer-title">${esc(el.dataset.title)}</h2><img src="assets/${el.dataset.gallery}" alt="${esc(el.dataset.title)}"><p class="dialog-caption">ご提供の実写写真</p>`);return;}if(el.dataset.work){window.history.replaceState(null,'','#'+el.dataset.work);renderWorks(el.dataset.work);return;}if(el.dataset.workDetail){openViewer(`<h2 id="viewer-title">${esc(el.dataset.workDetail)}</h2><p>施工実績</p>${btn('公式サイトで施工写真を見る ↗','https://www.kanehide-tekko.co.jp/sekoujisseki')}<p class="dialog-caption">工事名の出典：金秀鉄工公式サイト「施工実績」</p>`);return;}if(el.dataset.movie){playMovie(el.dataset.movie);return;}if(el.tagName==='A'){const href=el.getAttribute('href');if(href?.startsWith('http')){el.target='_blank';el.rel='noopener';return;}if(href?.startsWith('#')||!href||href.startsWith('tel:'))return;closeMenu();if(/^[a-z-]+\.html(?:#.*)?$/.test(href)&&href.split('#')[0]!==currentPage+'.html'&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();if(matchMedia('(prefers-reduced-motion:reduce)').matches){location.href=href;}else{document.body.classList.add('leaving');setTimeout(()=>{location.href=href;},260);}}}});
let revealObserver,countObserver;
function setupMotion(){const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;revealObserver?.disconnect();countObserver?.disconnect();revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target);}}),{threshold:.09});$$('.reveal').forEach(e=>{if(reduce)e.classList.add('visible');else revealObserver.observe(e);});countObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){countObserver.unobserve(e.target);const end=+e.target.dataset.count;if(reduce)return;let start;function frame(t){start??=t;const p=Math.min((t-start)/1300,1);e.target.textContent=formatStatValue(Math.round(end*(1-Math.pow(1-p,3))),e.target.dataset.grouping!=='false');if(p<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);}}),{threshold:.75});$$('[data-count]').forEach(e=>countObserver.observe(e));const video=$('#hero-video');if(video){video.muted=true;video.addEventListener('playing',()=>video.classList.add('ready'));if(reduce){video.pause();$('#motion-toggle').innerHTML='▶ <span>PLAY</span>';$('#motion-toggle').setAttribute('aria-label','背景映像を再生');}else video.play().catch(()=>{$('#motion-toggle').innerHTML='▶ <span>PLAY</span>';$('#motion-toggle').setAttribute('aria-label','背景映像を再生');});$('#motion-toggle').addEventListener('click',()=>{if(video.paused){video.style.display='block';video.play().then(()=>{$('#motion-toggle').innerHTML='Ⅱ <span>PAUSE</span>';$('#motion-toggle').setAttribute('aria-label','背景映像を一時停止');}).catch(()=>{video.classList.remove('ready');});}else{video.pause();$('#motion-toggle').innerHTML='▶ <span>PLAY</span>';$('#motion-toggle').setAttribute('aria-label','背景映像を再生');}});}}
window.addEventListener('scroll',()=>$('#header').classList.toggle('scrolled',scrollY>30),{passive:true});window.addEventListener('hashchange',()=>{if(currentPage==='works')renderWorks(location.hash.slice(1));if(currentPage==='news'){renderNews();window.scrollTo({top:0,behavior:'instant'});}});window.addEventListener('pageshow',()=>document.body.classList.remove('leaving'));
document.body.classList.toggle('inner',currentPage!=='index');document.body.classList.toggle('division-page',['steel','bridge','frp','pile'].includes(currentPage));setupMotion();if(currentPage==='gallery')setupGallery();if(currentPage==='contact')setupContactForm();
